import{_ as t,l as n,o as a,c as d,v as c,p as r,x as s,d as i,i as l,S as f}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"fsync","description":"","frontmatter":{"title":"fsync","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/fsync.md","filePath":"cs/fsync.md","lastUpdated":1789023840000}'),p={name:"cs/fsync.md"};function h(_,e,E,y,m,u){const o=n("Mermaid");return a(),d("div",null,[e[1]||(e[1]=c('<h1 id="fsync" tabindex="-1">fsync <a class="header-anchor" href="#fsync" aria-label="Permalink to &quot;fsync&quot;">​</a></h1><div class="epigraph"><p>fsync 要求该文件的脏数据以及必要的元数据到达稳定存储之后才返回；write 本身不提供这条保证。</p><footer>—— 据 POSIX fsync；McKusick 对 FFS 稳定存储的讨论</footer></div><p><a href="/cs/writeback">上一课</a>是后台尽力。<a href="/cs/buffer-dirty">缓冲与脏页</a> 已点名 fsync。缺口是<strong>同步点</strong>：谁等待、等待哪些块（数据页、inode、目录项、日志）、以及 <code>fdatasync</code> / <code>O_SYNC</code> 如何减范围。不是崩溃后如何重放——那是日志课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>编辑器保存若只 <code>write</code>，电源一断文件可能是旧的或空洞。若每次 <code>write</code> 都同步，交互式程序卡死。缺口：<code>fsync(fd)</code> 把该 inode 的脏页与元数据排队并等待设备完成（含存储控制器的 flush 命令，若平台提供）。失败要返回错误；成功后 POSIX 允许假定内容持久——硬件谎报则 OS 无法挽救。</p><p>本课不把每个控制器的 <code>FLUSH</code>/<code>FUA</code> 编码写完。</p><p><span class="marginnote"><code>fdatasync</code> 可不把未改的 inode 时间等元数据刷出。<code>O_SYNC</code> 让每次写都等价带同步。目录持久还要对目录 fd 做 fsync，否则新文件名可能丢。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>内核：对该 file 的页 Cache 做 writeback，提交 inode 与必要间接块，下发设备缓存刷新，睡眠直到完成 IRQ。与 <a href="/cs/writeback">writeback</a> 共用 <code>writepages</code>，只是调用者等待。多线程对同一文件 fsync 可合并。不要假设 <code>close</code> 等于 fsync——POSIX 不要求 close 刷盘。</p>',9)),(a(),r(f,null,{default:s(()=>[l(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20FS%5B%22fsync%22%5D%20--%3E%20WP%5B%22%E5%86%99%E8%84%8F%E9%A1%B5%E4%B8%8E%E5%85%83%E6%95%B0%E6%8D%AE%22%5D%0A%20%20WP%20--%3E%20FLUSH%5B%22%E8%AE%BE%E5%A4%87%E7%A8%B3%E5%AE%9A%E7%BC%93%E5%AD%98%22%5D%0A%20%20FLUSH%20--%3E%20RET%5B%22%E6%88%90%E5%8A%9F%E6%89%8D%E8%BF%94%E5%9B%9E%22%5D%0A"})]),fallback:s(()=>[...e[0]||(e[0]=[i(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=c('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>fsync 把「脏」从性能优化接回正确性接口：数据库、编辑器、安装器在关键点调用它。它不能单独保证崩溃一致性——只保证这一个文件的某些块顺序到达；目录项与 inode 的相对顺序仍可能错，于是需要下一课日志。本课只钉等待。</p><p>与 <a href="/cs/wal">WAL</a> 对照：数据库用自己的日志加 fsync；文件系统可以在下面再做一份，对象不同。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 <code>syncfs</code> 整机刷的全部语义。不把电池后备磁盘当默认从而宣称 fsync 可空操作。下一课 ext4 用日志把多次元数据更新捆成原子，减少 fsync 次数与 fsck。</p><p>后课默认：程序可以等待单文件持久。元数据多块原子，下一课日志模式。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>fsync 等待该文件脏数据与必要元数据落稳定存储。</li><li>close 不是 fsync；目录名要另刷。</li><li>多块元数据的原子性是日志课的缺口。</li><li>出处：POSIX.1 <code>fsync</code>；McKusick et al., <em>4.4BSD</em>；Silberschatz et al., <em>OSC</em>。</li></ul>',8))])}const b=t(p,[["render",h]]);export{A as __pageData,b as default};
